from pathlib import Path
import base64,hashlib,json
ROOT=Path.cwd();OUT=ROOT/'outputs/stem_observation_file_transport_20261011_v1'
h=lambda x:hashlib.sha256(x).hexdigest()
observer=base64.b64decode('',validate=True)
local=(ROOT/'outputs/stem_component12_20261011_v1/observe_payload64_v1.py').read_bytes()
assert local==observer+b'\n'
assert h(observer)=='f3ca1c798652ba7b8f2330256f321f86b45806b6f35ccad295acfea0b12bffa6'
source=json.loads(r'''{"1":{"base64":"","expected_sha256":"df7fdac552b34ea7f8cecfe559fcab9f33bd46f0d57c360e5dfaa4efe6b4a6b8","expected_bytes":588},"2":{"base64":"","expected_sha256":"ab0d1b54b1f17deba9edf9d183689627cdc1d0c9845c49f4dcc950182bdcc191","expected_bytes":588}}''')
payloads={};raws={}
for seed in (1,2):
    s=source[str(seed)];raw=base64.b64decode(s['base64'],validate=True)
    assert len(raw)==s['expected_bytes'] and h(raw)==s['expected_sha256']
    meta=json.loads(raw);assert meta['seed']==seed and meta['no_model_forwards'] and meta['no_training_restarts']
    assert meta['same_observer_source_sha256']==h(observer)
    path=OUT/f'seed{seed}_observation_v2.payload.json';b=path.read_bytes()
    assert len(b)==meta['payload_bytes'] and h(b)==meta['payload_sha256']
    raws[seed]=raw;payloads[str(seed)]=dict(file=path.name,bytes=len(b),sha256=meta['payload_sha256'])
names=[OUT/'observe_payload64_exact_executed_v1.py',OUT/'observation_transport_v2.json',OUT/'metadata_persist_v2_failure.json']+[OUT/f'seed{s}_metadata_v2.json' for s in (1,2)]
assert not any(p.exists() for p in names)
with (OUT/'observe_payload64_exact_executed_v1.py').open('xb') as f:f.write(observer)
for seed in (1,2):
    with (OUT/f'seed{seed}_metadata_v2.json').open('xb') as f:f.write(raws[seed])
with (OUT/'metadata_persist_v2_failure.json').open('x',encoding='utf8') as f:
    json.dump(dict(status='LOCAL_METADATA_BINDING_CHECK_FAILED_BEFORE_ANY_OUTPUT',reason='Prior local apply_patch observer file has exactly one additional newline compared with the unchanged executed source.',
      prior_local_sha256=h(local),executed_source_sha256=h(observer),repair='Save exact executed source bytes in a separate file and bind this transport to it.',
      training_restarts=0,training_code_changes=0,model_forwards=0),f,indent=2)
with (OUT/'observation_transport_v2.json').open('x',encoding='utf8') as f:
    json.dump(dict(schema='stem_live_observation_transport_v1',observer_source='outputs/stem_observation_file_transport_20261011_v1/observe_payload64_exact_executed_v1.py',payloads=payloads,
      scope='Unchanged read-only observer, exact source/raw JSON bytes transferred and bound; no trainer restart.'),f,indent=2)
print('PASS_EXACT_REMOTE_FILE_OBSERVATION_METADATA_SOURCE_AND_PAYLOADS')

